def trafficSignal(timer):
    # Exact matches first
    if timer == 0:
        return "Green"
    if timer == 30:
        return "Orange"
    # Red covers 31 through 90 inclusive
    if 30 < timer <= 90:
        return "Red"
    # Anything else is not a valid signal state
    return "Invalid"
